testsCode:
#include <stdio.h>

/* teste do desafio divisao-segura — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: o teste declara o prototipo da caixa do aluno no topo e
   confere o RETORNO com checa_int — nenhuma captura de tela aqui.

   POR QUE O VALOR COMBINADO DA GUARDA E -1, E NAO 0 (medido nesta maquina
   com cc -std=c11 -g, aluno e teste em arquivos separados): dividir por
   zero e comportamento indefinido em C, e aqui o programa NAO quebra —
   `7 / 0` devolve 0 caladamente. Logo, uma guarda que devolvesse 0 seria
   indistinguivel da divisao SEM guarda, e o cenario 2 aprovaria quem nunca
   escreveu a guarda. Com -1, so passa quem escreveu. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int divisaoSegura(int a, int b);

/* cenario 1 — o caminho normal: a divisao inteira acontece */
SM_TEST(divide_normalmente) {
    checa_int("7 dividido por 2", divisaoSegura(7, 2), 3,
              "entre inteiros a divisao corta: 7 / 2 e 3");
    checa_int("20 dividido por 5", divisaoSegura(20, 5), 4,
              "outro par de numeros: a caixa faz a conta, nao devolve valor fixo");
}

/* cenario 2 — o caminho da guarda: divisor zero devolve o valor combinado */
SM_TEST(divisor_zero_devolve_o_combinado) {
    checa_int("7 dividido por 0", divisaoSegura(7, 0), -1,
              "com b igual a 0 a guarda encerra a caixa e devolve o -1 combinado");
    checa_int("100 dividido por 0", divisaoSegura(100, 0), -1,
              "o valor de a nao muda a saida da guarda: com divisor 0 a resposta e -1");
}

solutionCode:
#include <stdio.h>

int divisaoSegura(int a, int b) {
    if (b == 0) {
        return -1;
    }
    return a / b;
}
